export type TouchRegion = 'head' | 'body' | 'legs';
export type TouchPoint = { x: number; y: number };
export type TouchFrame = { origin: TouchPoint; x: TouchPoint; y: TouchPoint };
export type TouchShape = { kind: 'ellipse'; center: TouchPoint; radius: TouchPoint } | { kind: 'polygon'; points: TouchPoint[] };
export type TouchArea = { id: string; name: string; shape: TouchShape };
export type TouchGesture = 'poke' | 'pet' | 'drop' | 'shake';
export type TouchRule = { gesture: TouchGesture; area: string; reaction: 'inherit' | 'auto' | 'default' | 'action' | 'none'; send: 'local' | 'next' | 'inherit'; note?: string; action?: { word?: string; resource?: string; release?: string; overlays?: string[] } };
export type TouchProfile = { areas: TouchArea[]; rules: TouchRule[]; areaNotes?: Record<string, string> };
export type TouchShapeTool = 'rectangle' | 'ellipse' | 'polygon';
export const TOUCH_REGION_CUTS: readonly [number, number];
export const TOUCH_REGIONS: Readonly<Record<TouchRegion, [string, string]>>;
export const TOUCH_GESTURES: readonly TouchGesture[];
export function readTouchRegion(value: unknown): TouchRegion | undefined;
export function touchRegion(bounds: { y: number; h: number } | null | undefined, y: number): TouchRegion | undefined;
export function readTouchProfile(value: unknown): TouchProfile;
export function touchRectangle(bounds: { left:number; top:number; right:number; bottom:number }): TouchShape;
export function touchShapeFromDrag(tool: unknown, start: TouchPoint | undefined, end: TouchPoint | undefined): TouchShape | undefined;
export function assertTouchOutline(shape: TouchShape): void;
export function resolvedTouchAreas(areas?: readonly TouchArea[]): TouchArea[];
export function touchShapeVertices(shape: TouchShape): TouchPoint[];
export function touchAreaConflict(areas: readonly TouchArea[], previous?: readonly TouchArea[], only?: string): [TouchArea, TouchArea] | undefined;
export function assertTouchAreaChange(areas: readonly TouchArea[], previous?: readonly TouchArea[]): void;
export function touchRegionAt(profile: TouchProfile | null | undefined, frame: TouchFrame | null | undefined, bounds: { y: number; h: number } | null | undefined, point: TouchPoint): string | undefined;
export function pointInTouchShape(shape: TouchShape, point: TouchPoint): boolean;
export function touchLocal(frame: TouchFrame | null | undefined, point: TouchPoint): TouchPoint | undefined;
export function touchScreen(frame: TouchFrame, point: TouchPoint): TouchPoint;
export function touchArea(profile: TouchProfile | null | undefined, frame: TouchFrame | null | undefined, point: TouchPoint): TouchArea | undefined;
export function touchSuggestion(resources: Array<{id:string;title:string;classification:string;group?:string}>|undefined, gesture:string, area:string): TouchRule['action'] | undefined;
export function touchRule(profile: TouchProfile | null | undefined, gesture: unknown, area: unknown): TouchRule | undefined;
